async function waitFor(fn, timeout, desc) {
  const end = Date.now() + timeout;
  let err = null;
  for (;;) {
    try { const v = await fn(); if (v) return v; } catch (e) { err = e; }
    if (Date.now() > end) throw new Fail(`timeout (${timeout} ms) waiting for ${desc}${err ? ': ' + err.message : ''}`);
    await sleep(60);
  }
}
