class WsConn {
  constructor(socket, head, tUpgrade) {
    this.socket = socket; this.tUpgrade = tUpgrade; this.buf = Buffer.alloc(0);
    this.frames = []; this.texts = []; this.closed = false; this.gotClose = false; this.closeCode = null;
    this.serverMasked = false; this.sentClose = false; this.frag = null;
    socket.setNoDelay(true);
    socket.on('data', (d) => this._data(d));
    socket.on('close', () => { this.closed = true; this.closedAt = Date.now(); });
    socket.on('error', () => {});
    if (head && head.length) this._data(head);
  }
  _data(d) {
    this.buf = Buffer.concat([this.buf, d]);
    for (;;) {
      const b = this.buf;
      if (b.length < 2) return;
      const fin = (b[0] & 0x80) !== 0, op = b[0] & 0x0f, masked = (b[1] & 0x80) !== 0;
      let len = b[1] & 0x7f, off = 2;
      if (len === 126) { if (b.length < 4) return; len = b.readUInt16BE(2); off = 4; }
      else if (len === 127) { if (b.length < 10) return; len = Number(b.readBigUInt64BE(2)); off = 10; }
      let mask = null;
      if (masked) { if (b.length < off + 4) return; mask = b.subarray(off, off + 4); off += 4; }
      if (b.length < off + len) return;
      const payload = Buffer.from(b.subarray(off, off + len));
      if (mask) for (let i = 0; i < payload.length; i++) payload[i] ^= mask[i & 3];
      this.buf = b.subarray(off + len);
      if (masked) this.serverMasked = true;
      this._frame(fin, op, payload);
    }
  }
  _frame(fin, op, payload) {
    if (op === 0x8) {
      this.gotClose = true; this.closeAt = Date.now();
      this.closeCode = payload.length >= 2 ? payload.readUInt16BE(0) : null;
      if (!this.sentClose) { this.sentClose = true; this._send(0x8, payload.subarray(0, 2)); }
      setTimeout(() => this.socket.destroy(), 200);
      return;
    }
    if (op === 0x9) { this._send(0xA, payload); return; }
    if (op === 0xA) return;
    if (op === 0x0) {
      if (this.frag) { this.frag.data = Buffer.concat([this.frag.data, payload]); if (fin) { this._msg(this.frag.op, this.frag.data); this.frag = null; } }
      return;
    }
    if (!fin) { this.frag = { op, data: payload }; return; }
    this._msg(op, payload);
  }
  _msg(op, data) { const rec = { t: Date.now(), data }; if (op === 0x2) this.frames.push(rec); else if (op === 0x1) this.texts.push(rec); }
  _send(op, payload = Buffer.alloc(0)) {
    if (this.socket.destroyed) return;
    const mask = crypto.randomBytes(4), len = payload.length;
    let h;
    if (len < 126) h = Buffer.from([0x80 | op, 0x80 | len]);
    else { h = Buffer.alloc(4); h[0] = 0x80 | op; h[1] = 0x80 | 126; h.writeUInt16BE(len, 2); }
    const body = Buffer.from(payload);
    for (let i = 0; i < body.length; i++) body[i] ^= mask[i & 3];
    this.socket.write(Buffer.concat([h, mask, body]));
  }
  sendText(s) { this._send(0x1, Buffer.from(s)); }
  get ended() { return this.closed || this.gotClose; }
  close() {
    if (!this.sentClose && !this.socket.destroyed) { this.sentClose = true; const p = Buffer.alloc(2); p.writeUInt16BE(1000); this._send(0x8, p); }
    setTimeout(() => this.socket.destroy(), 300);
  }
  async until(pred, timeout) { const end = Date.now() + timeout; while (!pred()) { if (Date.now() > end) return false; await sleep(15); } return true; }
}
function wsOpen(T, p, timeout = 3000) {
  return new Promise((resolve) => {
    const u = new URL(p, T.base + '/');
    const key = crypto.randomBytes(16).toString('base64');
    let done = false;
    const fin = (v) => { if (!done) { done = true; clearTimeout(timer); resolve(v); } };
    const rq = http.request({ hostname: u.hostname, port: u.port || 80, path: u.pathname + u.search, method: 'GET', agent: false,
      headers: { Connection: 'Upgrade', Upgrade: 'websocket', 'Sec-WebSocket-Version': '13', 'Sec-WebSocket-Key': key } });
    const timer = setTimeout(() => { rq.destroy(); fin({ status: 0, error: 'no answer to the upgrade request' }); }, timeout);
    rq.on('upgrade', (res, socket, head) => {
      const accept = crypto.createHash('sha1').update(key + WS_GUID).digest('base64');
      fin({ status: res.statusCode, headers: res.headers, acceptOk: res.headers['sec-websocket-accept'] === accept, ws: new WsConn(socket, head, Date.now()) });
    });
    rq.on('response', (res) => { const c = []; res.on('data', (d) => c.push(d)); res.on('end', () => fin({ status: res.statusCode, headers: res.headers, body: Buffer.concat(c).toString() })); });
    rq.on('error', (e) => fin({ status: 0, error: e.message }));
    rq.end();
  });
}
// binary frame layout [rc4b:1974-1991 pushLive()]: 'H', 1, bri, n0, n1, n0 x RGB, n1 x RGB
function checkFrame(d) {
  ok(d.length >= 5, `frame of ${d.length} bytes is shorter than the 5-byte header`);
  const f = { magic: d[0], ver: d[1], bri: d[2], n0: d[3], n1: d[4], len: d.length };
  ok(f.magic === 0x48, `byte 0 = 0x${f.magic.toString(16)}, expected 0x48 ('H')`);
  ok(f.ver === 1, `byte 1 (version) = ${f.ver}, expected 1`);
  ok(f.n0 <= WS_SAMPLES && f.n1 <= WS_SAMPLES, `n0=${f.n0} n1=${f.n1}, at most ${WS_SAMPLES} each`);
  ok(d.length === 5 + 3 * (f.n0 + f.n1), `frame length ${d.length} != 5+3*(n0+n1) = ${5 + 3 * (f.n0 + f.n1)}`);
  return f;
}

// ------------------------------------------------------------------------------------------------ test runner

const results = [];
let section = '';
const ctx = { main: null, pinT: null, kd: null, pinWhy: '', kdWhy: '', ws: false, segs: false, cfgTouched: false, ledTouched: false, relayTouched: false, children: [] };

function blocked(need) {
  for (const n of need) {
    switch (n) {
      case 'L': if (opt.hw && !opt.allowLeds) return 'hw: changes LEDs (add --allow-leds)'; if (!ctx.segs) return 'LED 1 / LED 2 segment missing on the target'; break;
      case 'C': if (opt.hw && !opt.allowCfg) return 'hw: writes the configuration (add --allow-cfg)';
        if (ctx.main.pinSet && !ctx.main.pin) return 'settings PIN set on the target (add --pin)'; break;
      case 'X': if (opt.hw && !opt.allowRelays) return 'hw: switches a relay (add --allow-relays)'; break;
      case 'NOHW': if (opt.hw) return 'never in --hw (several relays, scenes, relay settings)'; break;
      case 'FRESH': if (!opt.fresh) return 'needs a freshly started instance (--spawn-vdev or --spawn)'; break;
      case 'PINMOCK': if (!opt.spawn || !ctx.pinT) return 'needs the legacy PIN instance (--spawn)'; break;
      case 'PIN': if (!ctx.pinT) return ctx.pinWhy || 'no target with a settings PIN'; break;
      case 'KD': if (!ctx.kd) return ctx.kdWhy || 'no key-delay target'; break;
      case 'W': if (!ctx.ws) return 'websocket tests off (--ws)'; break;
      case 'NOPIN': if (ctx.main.pinSet) return 'target has a settings PIN'; break;
      default: throw new Error(`unknown need ${n}`);
    }
  }
  return null;
}
function sec(name) { section = name; console.log(`\n== ${name}`); }
async function t(id, title, refs, need, fn) {
  if (opt.only && !opt.only.test(`${id} ${title}`)) return;
  const tag = tagOf(refs);
  const why = blocked(need || []);
  if (why) { results.push({ id, tag, title, refs, section, status: 'SKIP', why }); console.log(`SKIP ${id} [${tag}] ${title} (${why})`); return; }
  if ((need || []).includes('L')) ctx.ledTouched = true;
  if ((need || []).includes('X')) ctx.relayTouched = true;
  const t0 = Date.now();
  try {
    await fn();
    results.push({ id, tag, title, refs, section, status: 'PASS', ms: Date.now() - t0 });
    console.log(`PASS ${id} [${tag}] ${title}`);
  } catch (e) {
    const msg = e instanceof Fail ? e.message : `${e.name}: ${e.message}${e instanceof TypeError ? ' (a field the firmware sends is missing; see the B*/E* shape tests)' : ''}`;
    results.push({ id, tag, title, refs, section, status: 'FAIL', msg, ms: Date.now() - t0 });
    console.log(`FAIL ${id} [${tag}] ${title} [${fmtRefs(refs)}]\n       ${msg}`);
    if (opt.verbose && !(e instanceof Fail)) console.log(e.stack);
    await sleep(Math.max(800, opt.settle));  // let a wrongly accepted upload / queued command finish before the next test
  }
}

// ------------------------------------------------------------------------------------------------ mock spawning

// true if something already accepts connections on the port (then a spawned server could not bind, and the readiness
// probe would silently test someone else's instance)
function portBusy(port) {
  return new Promise((resolve) => {
    const s = require('net').connect({ host: '127.0.0.1', port }, () => { s.destroy(); resolve(true); });
    s.on('error', () => resolve(false));
    s.setTimeout(1000, () => { s.destroy(); resolve(false); });
  });
}
async function startMock(name, port, args, script) {
  script = script || path.join(__dirname, 'server.js');
  if (await portBusy(port)) return { name, port, cmd: `node ${path.basename(script)} --port ${port}`, error: `port ${port} is already in use by another process (choose another --port)` };
  return startMockNow(name, port, args, script);
}
function startMockNow(name, port, args, script) {
  return new Promise((resolve) => {
    const full = [path.basename(script), '--port', String(port), ...args];
    const child = spawn(process.execPath, full, { cwd: path.dirname(script), stdio: ['ignore', 'pipe', 'pipe'] });
    ctx.children.push(child);
    let out = '';
    child.stdout.on('data', (d) => { out = (out + d).slice(-4000); });
    child.stderr.on('data', (d) => { out = (out + d).slice(-4000); });
    let exited = false;
    child.on('exit', (code) => { exited = true; if (!resolved) finish({ error: `exited with code ${code}: ${out.trim().slice(-600)}` }); });
    let resolved = false;
    const finish = (v) => { if (!resolved) { resolved = true; resolve(Object.assign({ name, port, cmd: `node ${path.relative(process.cwd(), script) || full[0]} ${full.slice(1).join(' ')}` }, v)); } };
    const base = `http://127.0.0.1:${port}`;
    const t0 = Date.now();
    (async () => {
      while (!resolved && !exited && Date.now() - t0 < 45000) {
        try { const r = await request(base, 'GET', '/home/cfg', { timeout: 2000 }); if (r.status === 200 && r.json) return finish({ base, ms: Date.now() - t0 }); } catch (e) { /* not up yet */ }
        await sleep(250);
      }
      finish({ error: `not ready after 45 s: ${out.trim().slice(-600)}` });
    })();
  });
}
function stopMocks() { for (const c of ctx.children) { try { c.kill(); } catch (e) { /* ignore */ } } ctx.children = []; }
process.on('exit', stopMocks);
process.on('SIGINT', () => { stopMocks(); process.exit(130); });

