// ---------- key not generated yet ([cpp:1407] the key appears ~5 s after Wi-Fi; until then it is "")
async function suiteKeyDelay() {
  sec('key not generated yet (key-delay instance)');
  const K = ctx.kd;
  // [cpp:971] key is sent as-is, [cpp:407] it starts empty, [cpp:1407-1410] generated later
  await t('K1', 'GET /home/cfg delivers key "" while no key exists', 'cpp:407,971,1407-1410', ['KD'], async () => {
    const c = await getCfg(K);
    eq(c.key, '', 'cfg.key');
  });
  // [cpp:1211-1212] "an empty (not yet generated) key never matches", [cpp:2046-2049] 403
  await t('K2', '/home/api answers 403 to k= and to no k while the key is empty', 'cpp:1211-1212,2046-2049', ['KD'], async () => {
    for (const q of ['relay=1&on=1&k=', 'relay=1&on=1', 'alloff=1&k=']) expectStatus(await api(K, q), 403, `GET /home/api?${q}`);
    const l = await settled(K);
    eq(l.r[0], 0, 'relay 1 after the refused /home/api?relay=1&on=1&k=');
  });
  // [cpp:2108-2111] key check first, keyOk("") is false [cpp:1212]
  await t('K3', 'POST /home/cfg?k= answers 403 while the key is empty', 'cpp:1212,2108-2111', ['KD'], async () => {
    expectStatus(await postCfg(K, { v: 1 }, { k: '' }), 403, 'POST /home/cfg?k=');
    expectStatus(await postCfg(K, { v: 1 }, { k: null }), 403, 'POST /home/cfg without k');
  });
  // [cpp:2215, 2224] keyValid = keyOk(um["k"] | "") is false for "" -> relay command dropped
  await t('K4', 'JSON state relay with "k":"" is ignored while the key is empty', 'cpp:1212,2215,2222-2224', ['KD'], async () => {
    await hg(K, { relay: 0, on: true, k: '' });
    await hg(K, { relay: 0, on: true });
    const l = await settled(K);
    eq(l.r[0], 0, 'relay 1 after {"relay":0,"on":true,"k":""}');
  });
  // [rc4b:1942-1947 onWsEvent()] keyOk() also rejects while no key exists yet -> close
  await t('K5', '/home/ws?k= is closed while the key is empty', 'rc4b:1942-1947', ['KD', 'W'], async () => {
    const c = await wsOpen(K, '/home/ws?k=');
    if (c.ws) {
      const closed = await c.ws.until(() => c.ws.ended, 1500);
      const n = c.ws.frames.length; c.ws.close();
      ok(closed, 'connection still open 1.5 s after the upgrade');
      eq(n, 0, 'binary frames received');
    } else ok(c.status !== 101, `unexpected result ${fmt(c)}`);
  });
}

